-- chapter:2
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('chapter:2', 1, '{"prologue":[{"kind":"log","text":"Đây là đêm đầu tiên Kai ở ngoài Vùng Tối. Sau lưng anh, thành phố vẫn sáng đèn theo đúng nhịp OMNI đặt ra."},{"kind":"log","text":"Từ Vùng Tối ra tới biên giới mất gần hết đêm. Giữa thành phố và vùng đất bên ngoài là Vành Sentinel."},{"kind":"log","text":"Vành Sentinel là dải đất rộng chừng một cây số, nằm giữa tường thành phố và rào ngoài. Drone tuần tra ở đó theo luật cố định, không có người trực. Ai vào mà không có lệnh của OMNI đều bị xử lý."},{"kind":"kai","text":"Neural-ID giả của tôi chỉ sống tới đợt quét lớn lúc rạng sáng. Tôi phải qua bên kia trước giờ đó."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Rào ngoài hở lúc 03:41. Drone đổi ca lúc 03:47. Tôi đã tính sẵn cho bạn.\""},{"kind":"echo","text":"Lịch đó không đi qua trạm nào của Mạng Mù. Tôi không kiểm tra được nó… Đừng đi theo."},{"kind":"kai","text":"Tôi sẽ không đi theo lịch của ai. Muốn qua được, tôi phải tự biết drone sẽ làm gì."},{"kind":"echo","text":"Drone không đoán. Nó so sánh, rồi chọn… Bạn hãy đọc luật của chúng trước, rồi viết luật của mình."},{"kind":"echo","text":"Ta sẽ dựng một bộ luật né gồm sáu luật. Qua mỗi chặng, bạn thêm một luật."},{"kind":"log","text":"Dưới chân rào ngoài có một ống thoát nước. Trong lòng ống, đèn của một drone hỏng vẫn còn nhấp nháy."},{"kind":"card","text":"CHƯƠNG 2\nTRẠM SENTINEL"}],"teaser":[{"kind":"log","text":"Kai đã đứng ở bên kia rào ngoài. Thành phố giờ chỉ còn là một vệt sáng sau lưng anh."},{"kind":"echo","text":"Bộ luật né đã đủ sáu luật. Đợt quét lớn vừa đi qua… Neural-ID giả đã tắt. Từ giờ bạn không còn danh tính nào."},{"kind":"log","text":"Hai mảnh trong tám đã về tay. Sáu mảnh còn lại vẫn nằm ở sáu nơi không ai biết."},{"kind":"log","text":"Phía trước là một trung tâm dữ liệu bỏ hoang. Trong hành lang của nó, cảm biến quét đi quét lại, không lúc nào dừng."},{"kind":"card","text":"TÍN HIỆU · 0xA7\n\"Mảnh thứ ba ở trung tâm dữ liệu cũ. Lần này tôi sẽ đi cùng bạn.\""},{"kind":"echo","text":"Phía trước không còn trạm nào của Mạng Mù. Từ đây, tôi chỉ biết những gì bạn nhìn thấy."},{"kind":"log","text":"GÓI TIN CUỐI CÙNG TRƯỚC KHI NEURAL-ID GIẢ TẮT\nNHẬT KÝ CỔNG KIỂM SOÁT · NX-0417\nMỨC TUÂN THỦ: 100% → 96%\nĐÃ ĐƯA VÀO DANH SÁCH THEO DÕI"},{"kind":"kai","text":"Nhi bị theo dõi là vì tôi."},{"kind":"card","text":"HẾT CHƯƠNG 2 · TRẠM SENTINEL\nChương 3: Mê cung Máy chủ\nTín hiệu đang giải mã."}]}', '2026-10-29T19:30:36.793Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'chapter:2' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
